declare_lint ! { #[doc = " The `dangerous_implicit_autorefs` lint checks for implicitly taken references"] #[doc = " to dereferences of raw pointers."] #[doc = ""] #[doc = " ### Example"] #[doc = ""] #[doc = " ```rust,compile_fail"] #[doc = " unsafe fn fun(ptr: *mut [u8]) -> *mut [u8] {"] #[doc = "     unsafe { &raw mut (*ptr)[..16] }"] #[doc = "     //                      ^^^^^^ this calls `IndexMut::index_mut(&mut ..., ..16)`,"] #[doc = "     //                             implicitly creating a reference"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " {{produces}}"] #[doc = ""] #[doc = " ### Explanation"] #[doc = ""] #[doc = " When working with raw pointers it's usually undesirable to create references,"] #[doc = " since they inflict additional safety requirements. Unfortunately, it's possible"] #[doc = " to take a reference to the dereference of a raw pointer implicitly, which inflicts"] #[doc = " the usual reference requirements."] #[doc = ""] #[doc = " If you are sure that you can soundly take a reference, then you can take it explicitly:"] #[doc = ""] #[doc = " ```rust"] #[doc = " unsafe fn fun(ptr: *mut [u8]) -> *mut [u8] {"] #[doc = "     unsafe { &raw mut (&mut *ptr)[..16] }"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " Otherwise try to find an alternative way to achieve your goals using only raw pointers:"] #[doc = ""] #[doc = " ```rust"] #[doc = " use std::ptr;"] #[doc = ""] #[doc = " fn fun(ptr: *mut [u8]) -> *mut [u8] {"] #[doc = "     ptr::slice_from_raw_parts_mut(ptr.cast(), 16)"] #[doc = " }"] #[doc = " ```"] pub DANGEROUS_IMPLICIT_AUTOREFS , Deny , "implicit reference to a dereference of a raw pointer" , report_in_external_macro }